custom_css:
/* Magnum Opus Glass — Clean-room SillyTavern UI Theme for Lapis Philosophorum Engine (LPE).
 * Inspired by the dual-accent dark frosted glass palette of KAKAA / @rech0_viixi (CC BY-NC-SA 4.0)
 * and the streamlined sidebar ergonomics of deepsleep-claw/SleepTavernHome (AFPL v9).
 * 100% original implementation with zero external CDN fonts or assets. */
:root {
  --mo-bg: var(--SmartThemeBlurTintColor, rgba(29, 29, 32, 0.88));
  --mo-surface: var(--SmartThemeShadowColor, rgba(34, 34, 34, 1));
  --mo-border: var(--SmartThemeBorderColor, rgba(23, 23, 23, 1));
  --mo-text: var(--SmartThemeBodyColor, rgba(219, 219, 214, 1));
  --mo-muted: var(--SmartThemeEmColor, rgba(157, 157, 157, 1));
  --mo-accent-1: var(--SmartThemeQuoteColor, rgba(154, 214, 207, 1));
  --mo-accent-2: var(--SmartThemeUnderlineColor, rgba(241, 190, 154, 1));
  --mo-grad: linear-gradient(135deg, var(--mo-accent-1) 30%, color-mix(in srgb, var(--mo-accent-1) 50%, var(--mo-accent-2) 50%) 50%, var(--mo-accent-2) 70%);
  --mo-hairline: color-mix(in srgb, var(--mo-text) 12%, transparent);
  --mo-hairline-strong: color-mix(in srgb, var(--mo-text) 22%, transparent);
}
body {
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}
#top-bar,
#top-settings-holder .drawer-content,
#left-nav-panel,
#right-nav-panel,
#dialogue_popup,
.popup {
  background: color-mix(in srgb, var(--mo-bg) 92%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-color: var(--mo-hairline);
}
#top-settings-holder .drawer-icon.openIcon,
#top-settings-holder .drawer-icon:hover {
  color: var(--mo-accent-1);
}
#chat {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.22) transparent;
}
#chat .mes {
  margin: 10px 0;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid var(--mo-hairline);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 0.2s ease, background-color 0.2s ease;
}
#chat .mes:hover {
  border-color: var(--mo-hairline-strong);
}
#chat .mes[is_user="true"] {
  border-left: 3px solid color-mix(in srgb, var(--mo-accent-2) 70%, transparent);
}
#chat .mes:not([is_user="true"]) {
  border-left: 3px solid color-mix(in srgb, var(--mo-accent-1) 62%, transparent);
}
#chat .mes .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--mo-accent-1) 45%, transparent), 0 0 14px color-mix(in srgb, var(--mo-accent-2) 28%, transparent);
}
#chat .mes .name_text {
  font-family: Georgia, 'Palatino Linotype', 'Book Antiqua', serif;
  letter-spacing: 0.015em;
  color: #f2f2ee;
}
#chat .mes_text {
  font-family: Georgia, 'Palatino Linotype', 'Book Antiqua', serif;
  line-height: 1.72;
}
#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3 {
  font-family: Georgia, 'Palatino Linotype', 'Book Antiqua', serif;
  color: #f2f2ee;
}
#chat .mes_text h1::before,
#chat .mes_text h2::before {
  content: "✦ ";
  background: var(--mo-grad);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
#chat .mes_text blockquote {
  border-left: 3px solid var(--mo-accent-1);
  background: color-mix(in srgb, var(--mo-bg) 76%, transparent);
  border-radius: 0 8px 8px 0;
  padding: 8px 12px;
}
#chat .mes_text code,
#chat .mes_text pre {
  background: var(--mo-surface);
  border: 1px solid var(--mo-hairline);
  font-variant-numeric: tabular-nums;
}
#send_form {
  border-radius: 16px;
  border: 1px solid var(--mo-hairline);
  background: color-mix(in srgb, var(--mo-bg) 90%, transparent);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  margin-bottom: 6px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
#send_form:focus-within {
  border-color: color-mix(in srgb, var(--mo-accent-1) 58%, transparent);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4), 0 0 0 2px color-mix(in srgb, var(--mo-accent-1) 18%, transparent);
}
.inline-drawer-toggle,
#extensions_settings .inline-drawer-toggle {
  border-left: 3px solid color-mix(in srgb, var(--mo-accent-1) 68%, transparent);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.03);
  padding-left: 8px;
}
.inline-drawer-toggle.open,
#extensions_settings .inline-drawer-toggle.open {
  border-left-color: var(--mo-accent-2);
}
#completion_prompt_manager .completion_prompt_manager_prompt {
  border-left: 3px solid var(--mo-hairline);
  border-radius: 6px;
}
#completion_prompt_manager .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  opacity: 0.58;
}
.menu_button,
.interactable {
  transition: border-color 0.16s ease, background-color 0.16s ease;
}
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.22);
  border-radius: 999px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.36);
}
@media (max-width: 999.98px) {
  #chat .mes {
    padding: 10px 12px;
    margin: 7px 0;
  }
  #send_form {
    border-radius: 14px;
  }
}
